/* BIG LWA Reading Room / Lwasaurus. Private annotations, not public posts. */
(()=>{
'use strict';
if(window.BigLWAReadingRoom)return;
const KEY='biglwaReadingMemoryV1', ROOT='.bl-lwazi-answer-body,.bl-lwazi-turn,.bl-search-card-body,#libraryCatalog .lib-item-body,#journalReaderText,[data-lwa-reading-text]';
const $=(s,r=document)=>r.querySelector(s), all=(s,r=document)=>Array.from(r.querySelectorAll(s));
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
const btn=(text,fn)=>{const b=el('button',text);b.type='button';b.addEventListener('click',fn);return b};
const privateView=()=>window.__biglwaPublicStorageView||document.documentElement.classList.contains('biglwa-preview-mode')||!window.BigLWAAccountStorage?.uid;
const blank=()=>({highlights:[],documents:[]});
function read(){if(privateView())return blank();try{const v=JSON.parse(localStorage.getItem(KEY)||'null');return v&&Array.isArray(v.highlights)&&Array.isArray(v.documents)?v:blank()}catch{return blank()}}
function write(v){if(privateView())throw Error('Sign in to your own Studio to save privately.');localStorage.setItem(KEY,JSON.stringify(v));schedule()}
function pastel(raw){const n=(String(raw).match(/\d+(?:\.\d+)?/g)||[]).slice(0,3).map(Number);return '#'+(n.length===3?n:[216,95,109]).map(x=>Math.round(255*.55+Math.max(0,Math.min(255,x))*.45).toString(16).padStart(2,'0')).join('')}
function color(root){return pastel(getComputedStyle(root).getPropertyValue('--aura-rgb')||getComputedStyle(document.documentElement).getPropertyValue('--aura-rgb'))}
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(36)}
function identity(root){return (root.dataset.lwaReadingText?'doc:'+root.dataset.lwaReadingText:root.closest('.bl-search-panel')?'search':root.closest('#libraryCatalog')?'library':'journal')+':'+hash(root.textContent)}
function offset(root,node,pos){const r=document.createRange();r.selectNodeContents(root);r.setEnd(node,pos);return r.toString().length}
function rangeAt(root,start,end){const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n,at=0,a,b;while(n=w.nextNode()){const next=at+n.length;if(!a&&start>=at&&start<=next)a=[n,start-at];if(end>=at&&end<=next){b=[n,end-at];break}at=next}if(!a||!b)return null;const r=document.createRange();r.setStart(...a);r.setEnd(...b);return r}
let ownedNames=new Set(),active=null,toolbar=null,lookupGeneration=0,timer=0,activeDoc='',shownSignature='';
const colorOK=c=>/^#[0-9a-f]{6}$/i.test(c||'');
function paint(){if(!window.CSS?.highlights||!window.Highlight)return;for(const k of ownedNames)CSS.highlights.delete(k);ownedNames.clear();const byColor=new Map(),v=read();for(const root of all(ROOT)){const key=identity(root),content=root.textContent;for(const h of v.highlights){if(h.source!==key||!colorOK(h.color)||content.slice(h.start,h.end)!==h.quote)continue;const range=rangeAt(root,h.start,h.end);if(!range)continue;const list=byColor.get(h.color)||[];list.push(range);byColor.set(h.color,list)}}const rules=[];for(const [c,ranges] of byColor){const name='lwa-memory-'+c.slice(1);CSS.highlights.set(name,new Highlight(...ranges));ownedNames.add(name);rules.push('::highlight('+name+'){background-color:'+c+';color:#211b19}')}if(dynamic.textContent!==rules.join('\n'))dynamic.textContent=rules.join('\n')}
function selection(){const s=getSelection();if(!s||s.isCollapsed||!s.rangeCount||privateView())return null;const r=s.getRangeAt(0),node=r.commonAncestorContainer;const root=(node.nodeType===1?node:node.parentElement)?.closest(ROOT);if(!root||!root.contains(r.startContainer)||!root.contains(r.endContainer))return null;const quote=r.toString();if(!quote.trim()||quote.length>2000)return null;return{root,source:identity(root),quote,start:offset(root,r.startContainer,r.startOffset),end:offset(root,r.endContainer,r.endOffset),color:color(root),rect:r.getBoundingClientRect(),label:root.dataset.lwaReadingText?(read().documents.find(d=>d.id===root.dataset.lwaReadingText)?.title||'Reading Room'):root.closest('.bl-search-panel')?'Search / L’wazi':root.closest('#libraryCatalog')?'Library':'Journal'}}
function saveSelection(a,board=false){const v=read();let h=v.highlights.find(x=>x.source===a.source&&x.start===a.start&&x.end===a.end&&x.quote===a.quote);if(!h){h={id:crypto.randomUUID(),source:a.source,quote:a.quote,start:a.start,end:a.end,color:a.color,label:a.label,createdAt:new Date().toISOString(),note:'',board:false};v.highlights.unshift(h)}if(board)h.board=true;write(v);paint();return h}
function status(message){const n=$('[data-lwa-memory-status]',toolbar||document);if(n)n.textContent=message}
function hide(){if(toolbar)toolbar.hidden=true;active=null;lookupGeneration++}
function iconButton(label,asset,fn){const b=btn('',fn);b.title=label;b.setAttribute('aria-label',label);if(asset){const img=el('img');img.src=asset;img.alt='';b.append(img)}else b.textContent='▤';return b}
function showSelection(){const a=selection();if(!a){if(!toolbar?.contains(document.activeElement))hide();return}active=a;if(!toolbar){toolbar=el('aside',undefined,'lwa-memory-toolbar');toolbar.setAttribute('aria-label','Reading selection tools');toolbar.addEventListener('pointerdown',e=>{if(e.target.closest('button'))e.preventDefault()});const high=btn('Highlight',()=>{try{saveSelection(active);status('Highlight saved to your private reading notes.')}catch(e){status(e.message)}});high.className='lwa-memory-high';const board=iconButton('Save highlight to private Boards · Reading notes',null,()=>{try{saveSelection(active,true);status('Saved in Boards · Reading notes.')}catch(e){status(e.message)}});const hand=iconButton('L’wazi word meaning and origin','/assets/tools-hand-eye.svg',()=>{if(active)lookup(active.quote,$('.lwa-memory-result',toolbar))});hand.className='lwa-memory-hand';const close=btn('×',hide);close.setAttribute('aria-label','Close selection tools');const row=el('div',undefined,'lwa-memory-actions');row.append(high,board,hand,close);const message=el('small');message.dataset.lwaMemoryStatus='';message.setAttribute('role','status');toolbar.append(row,message,el('div',undefined,'lwa-memory-result'));document.body.append(toolbar)}toolbar.hidden=false;toolbar.style.setProperty('--memory-aura',a.color);$('.lwa-memory-result',toolbar).replaceChildren();status('');toolbar.style.left=Math.max(8,Math.min(innerWidth- Math.min(340,innerWidth-16),a.rect.left))+'px';toolbar.style.top=Math.max(8,Math.min(innerHeight-100,a.rect.bottom+8))+'px'}
const cache=new Map();
async function json(url){const res=await fetch(url,{credentials:'omit',signal:AbortSignal.timeout(10000)});if(!res.ok)throw Error('Source unavailable');return res.json()}
function cleanTerm(value){return String(value||'').trim().replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu,'').replace(/\s+/g,' ').slice(0,80).toLowerCase()}
async function wiki(term){const u='https://en.wiktionary.org/w/api.php?'+new URLSearchParams({action:'parse',page:term,prop:'text',format:'json',formatversion:'2',origin:'*'});const data=await json(u);if(!data.parse?.text)return{definitions:[],origins:[]};const doc=new DOMParser().parseFromString(data.parse.text,'text/html');let english=false,section='',definitions=[],origins=[];const wrap=doc.querySelector('.mw-parser-output')||doc.body;for(const node of wrap.children){const header=node.matches('h2,h3,h4,h5')?node:node.querySelector(':scope > h2,:scope > h3,:scope > h4,:scope > h5');if(header){if(header.tagName==='H2'){english=header.textContent.trim().replace(/\[edit\]/g,'').trim()==='English';section=''}else section=header.textContent.trim();continue}if(!english)continue;if(/^Etymology(?:\s|\[|$)/i.test(section)&&node.tagName==='P'&&origins.length<3)origins.push(node.textContent.trim().slice(0,800));if(/^(Noun|Verb|Adjective|Adverb|Pronoun|Preposition|Conjunction|Interjection|Proper noun|Phrase|Determiner|Numeral)/i.test(section)&&node.tagName==='OL'){for(const li of Array.from(node.children).slice(0,3)){const copy=li.cloneNode(true);copy.querySelectorAll('ul,ol,dl,.quotation').forEach(n=>n.remove());const t=copy.textContent.trim().slice(0,350);if(t&&definitions.length<8)definitions.push(section.replace(/\[edit\]/g,'').trim()+': '+t)}}}return{definitions,origins}}
async function related(term,relation){const rows=await json('https://api.datamuse.com/words?'+new URLSearchParams({[relation]:term,max:'18'}));return Array.isArray(rows)?rows.map(x=>String(x.word||'')).filter(Boolean):[]}
function link(label,url){const a=el('a',label);a.href=url;a.target='_blank';a.rel='noopener noreferrer';return a}
async function lookup(raw,host,onWord){const term=cleanTerm(raw);if(!term){host.textContent='Select or enter a word.';return}if(raw.trim().length>80){host.textContent='Select a shorter word or phrase for dictionary lookup.';return}const generation=++lookupGeneration;host.textContent='Looking up '+term+'…';let result=cache.get(term);if(!result){const rs=await Promise.allSettled([wiki(term),related(term,'rel_syn'),related(term,'rel_ant'),related(term,'ml')]);result={wiki:rs[0].status==='fulfilled'?rs[0].value:null,syn:rs[1].value||[],ant:rs[2].value||[],related:rs[3].value||[],failed:rs.some(x=>x.status==='rejected')};if(!result.failed&&cache.size<150)cache.set(term,result)}if(generation!==lookupGeneration||!host.isConnected)return;host.replaceChildren(el('h3',term));const add=(title,values)=>{if(!values?.length)return;host.append(el('b',title));const list=el('ul');for(const t of values)list.append(el('li',t));host.append(list)};add('Meaning',result.wiki?.definitions);add('Word origin',result.wiki?.origins);if(!result.wiki?.definitions?.length&&!result.wiki?.origins?.length)host.append(el('p','No English dictionary entry returned. Try the base form or a shorter phrase.'));for(const [title,words] of [['Synonyms',result.syn],['Antonyms',result.ant],['Related words (not necessarily synonyms)',result.related]]){if(!words.length)continue;host.append(el('b',title));const group=el('div',undefined,'lwa-word-chips');for(const word of words)group.append(btn(word,()=>{if(onWord)onWord(word);else lookup(word,host)}));host.append(group)}if(result.failed)host.append(el('small','One or more sources could not respond.'));const sources=el('p',undefined,'lwa-word-sources');sources.append(link('Wiktionary · CC BY-SA','https://en.wiktionary.org/wiki/'+encodeURIComponent(term)),' · ',link('Datamuse / WordNet','https://www.datamuse.com/api/'),' · ',link('Etymonline reference','https://www.etymonline.com/word/'+encodeURIComponent(term)),' · ',link('Cornell Wex · legal context','https://www.law.cornell.edu/wex/'+encodeURIComponent(term.replace(/ /g,'_'))));host.append(sources)}
function thesaurus(){const box=el('details',undefined,'lwa-memory-thesaurus');box.append(el('summary','Lwasaurus · word workshop'));const form=el('form'),input=el('input');input.type='search';input.placeholder='A word or short phrase';input.maxLength=80;input.required=true;input.setAttribute('aria-label','Lwasaurus word');const submit=el('button','Look up');submit.type='submit';const result=el('div',undefined,'lwa-memory-result');form.append(input,submit);form.addEventListener('submit',e=>{e.preventDefault();lookup(input.value,result,word=>{input.value=word;lookup(word,result)})});box.append(form,result);return box}
function notes(host,boardOnly){const v=read();host.replaceChildren();const rows=v.highlights.filter(h=>!boardOnly||h.board);if(!rows.length)host.append(el('p','Select text to start your private collection.'));for(const h of rows){const card=el('article',undefined,'lwa-memory-note'),q=el('mark',h.quote);if(colorOK(h.color))q.style.backgroundColor=h.color;q.style.color='#211b19';const meta=el('small',h.label+' · '+new Date(h.createdAt).toLocaleDateString());const note=el('textarea');note.value=h.note||'';note.placeholder='Your reading note…';note.maxLength=2000;note.setAttribute('aria-label','Note for '+h.quote.slice(0,50));const message=el('small');const update=btn('Save note',()=>{try{const next=read(),item=next.highlights.find(x=>x.id===h.id);if(!item)throw Error('Highlight no longer exists.');item.note=note.value;write(next);message.textContent='Note saved.'}catch(e){message.textContent=e.message}});const remove=btn(boardOnly?'Remove from board':'Delete highlight',()=>{try{const next=read();if(boardOnly){const item=next.highlights.find(x=>x.id===h.id);if(item)item.board=false}else next.highlights=next.highlights.filter(x=>x.id!==h.id);write(next);notes(host,boardOnly);paint()}catch(e){message.textContent=e.message}});card.append(q,meta,note,update,remove,message);host.append(card)}}
function readingPanel(host){const panel=el('section',undefined,'lwa-memory-panel');panel.dataset.lwaMemoryPanel='library';panel.append(el('h2','Reading Room'),el('p','Upload a text or Markdown document, highlight passages, and keep notes in your private account. Only a word or short phrase you explicitly look up is sent to dictionary providers.'));const input=el('input');input.type='file';input.accept='.txt,.md,text/plain,text/markdown';input.setAttribute('aria-label','Upload a reading document');const message=el('p');message.setAttribute('role','status');const list=el('div'),reader=el('article',undefined,'lwa-reading-sheet'),noteHost=el('div');const draw=()=>{const v=read();list.replaceChildren();for(const d of v.documents){const b=btn(d.title,()=>{activeDoc=d.id;draw()});list.append(b)}const d=v.documents.find(x=>x.id===activeDoc);reader.hidden=!d;reader.dataset.lwaReadingText=d?.id||'';reader.textContent=d?.text||'';if(d){const del=btn('Remove opened document',()=>{try{const next=read();next.documents=next.documents.filter(x=>x.id!==d.id);write(next);activeDoc='';draw()}catch(e){message.textContent=e.message}});list.append(del)}notes(noteHost,false);paint()};input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;const owner=window.BigLWAAccountStorage?.uid;try{if(!/\.(txt|md)$/i.test(file.name)||file.size>120000)throw Error('Choose a TXT or Markdown file under 120 KB.');const text=await file.text();if(owner!==window.BigLWAAccountStorage?.uid)throw Error('Account changed.');if(!text.trim())throw Error('This file is empty.');const v=read(),id=crypto.randomUUID();v.documents.unshift({id,title:file.name.slice(0,150),text,createdAt:new Date().toISOString()});write(v);activeDoc=id;draw();message.textContent='Document saved privately.'}catch(e){message.textContent=e.message}finally{input.value=''}});panel.append(input,message,list,reader,thesaurus(),el('h3','Your highlights & notes'),btn('Refresh notes',draw),noteHost);host.prepend(panel);draw();return {panel,refresh:()=>{notes(noteHost,false);paint()}}}
let panelState=null;
function mount(){if(privateView()){hide();return}const host=$('#moduleWorkspaceBody'),route=$('#moduleRouteName')?.textContent.trim().toLowerCase();if(!host||!['library','journal','boards'].includes(route))return;const kind=route;let panel=$('[data-lwa-memory-panel="'+kind+'"]',host);if(panel)return;if(kind==='library'){panelState=readingPanel(host);return}panel=el('section',undefined,'lwa-memory-panel');panel.dataset.lwaMemoryPanel=kind;if(kind==='journal'){panel.append(thesaurus());host.append(panel)}else{panel.append(el('h2','Reading notes'),el('p','Private text highlights pinned from your Reading Room or L’wazi. These are not Pinterest pins.'));const n=el('div');panel.append(btn('Refresh reading notes',()=>notes(n,true)),n);host.prepend(panel);notes(n,true)}}
function schedule(){clearTimeout(timer);timer=setTimeout(()=>{mount();paint()},100)}
const style=el('style');style.textContent='.lwa-memory-toolbar{position:fixed;z-index:2147483000;background:var(--widget-bg,#fffaf3);color:var(--widget-ink,#26211e);border:1px solid var(--memory-aura,#ecc5ce);box-shadow:0 5px 24px #0004;border-radius:10px;padding:9px;width:min(340px,calc(100vw - 16px));max-height:65vh;overflow:auto;font:13px/1.45 system-ui;box-sizing:border-box}.lwa-memory-toolbar[hidden]{display:none!important}.lwa-memory-actions,.lwa-word-chips{display:flex;gap:6px;flex-wrap:wrap;align-items:center}.lwa-memory-toolbar button,.lwa-memory-panel button{font:inherit;border:1px solid #8c807955;border-radius:7px;padding:6px 9px;background:var(--widget-bg,#fffaf3);color:inherit;cursor:pointer}.lwa-memory-toolbar .lwa-memory-high{background:var(--memory-aura);color:#211b19}.lwa-memory-hand img{width:24px;height:24px;filter:drop-shadow(0 0 5px var(--memory-aura))}.lwa-memory-panel{padding:14px;border:1px solid rgba(var(--aura-rgb,216,95,109),.3);border-radius:12px;margin:12px 0;background:var(--widget-bg,#fffaf3);color:var(--widget-ink,#26211e)}.lwa-memory-panel input,.lwa-memory-panel textarea{max-width:100%;font:inherit;color:inherit;background:transparent;border:1px solid #8c807955;border-radius:6px;padding:7px}.lwa-memory-note{display:grid;gap:6px;padding:9px 0;border-bottom:1px solid #8c807955}.lwa-memory-note mark{padding:3px;white-space:pre-wrap;overflow-wrap:anywhere}.lwa-memory-note textarea{width:100%;box-sizing:border-box;min-height:55px}.lwa-reading-sheet{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;padding:16px;max-height:65vh;overflow:auto;user-select:text}.lwa-memory-thesaurus form{display:flex;gap:6px;margin:8px 0;flex-wrap:wrap}.lwa-memory-result ul{padding-left:19px}.lwa-memory-result h3{margin:8px 0}.lwa-word-sources{font-size:11px}.lwa-memory-panel summary{cursor:pointer;font-weight:700}.lwa-memory-panel small{opacity:.8}';
const dynamic=el('style');document.head.append(style,dynamic);
let selectTimer=0;document.addEventListener('selectionchange',()=>{clearTimeout(selectTimer);selectTimer=setTimeout(showSelection,180)});document.addEventListener('pointerdown',e=>{if(toolbar&&!toolbar.contains(e.target)&&!e.target.closest?.(ROOT))hide()});document.addEventListener('keydown',e=>{if(e.key==='Escape')hide()});window.addEventListener('resize',hide);
const observer=new MutationObserver(records=>{if(records.some(r=>!toolbar?.contains(r.target)&&r.target!==dynamic&&!r.target.closest?.('[data-lwa-memory-panel]')))schedule()});observer.observe(document.body,{childList:true,subtree:true,characterData:true});window.addEventListener('biglwa:account-storage-status',schedule);window.BigLWAReadingRoom=Object.freeze({refresh:schedule,pastel});schedule();
})();